// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount) public {
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        Reverter r = new Reverter();
        address caller = address(r);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        Reverter r2 = new Reverter();
        address caller2 = address(r2);
        bool refReverted;
        try c.withdrawAll() {
            vm.prank(caller2);
            refReverted = false;
        } catch {
            refReverted = true;
        }
        assertTrue(!refReverted);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
